 fn admit_selection(instance:u32,surface:Option<&str>,cx:&mut StepContext<'_>,admission:&mut OriginalConstructionAdmission,failure:&mut Option<OriginalConstructionFailure>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{let d=RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<Self>()};let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;born(cx,output,admission,failure,d,|native|{let decoder=(native.ledger_identity(),native.retirement_recipient_identity().ok_or_else(invalid)?);Ok(Box::new(Self{instance,binding,decoder,body,surface:surface.map(|surface|(surface.as_ptr()as usize,surface.len())),frame:Default::default(),frame_failure:ManuallyDrop::new(None),capture:ManuallyDrop::new(None),owned_view:ManuallyDrop::new(None),view:ManuallyDrop::new(None),lease:ManuallyDrop::new(None),allocation:Default::default(),actor:ManuallyDrop::new(None),metadata:ManuallyDrop::new(None),actor_source:None,offset:0,phase:0,retirement:Default::default()}))})}
