 fn validate_surface(&self,surface:Option<&str>)->Result<(),OriginalTurnFailure>{if self.surface!=surface.map(|surface|(surface.as_ptr()as usize,surface.len())){return Err(invalid().into())}Ok(())}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 fn advance_cache(&mut self,surface:Option<&str>,registry:&mut semio_plugin_plugin_program::surface_context::SurfaceContexts,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;self.validate_surface(surface)?;match self.phase{0=>{if self.capture.is_none(){OriginalSurfaceViewCapture::admit(cx,&mut self.frame,&mut self.frame_failure,&mut self.capture)?;return Ok(false)}if match surface{Some(surface)=>self.capture.as_mut().unwrap().advance_surface(registry,surface,cx)?,None=>self.capture.as_mut().unwrap().advance(registry,cx)?}{self.phase=1}},1=>{if self.capture.as_mut().unwrap().take_into(&mut self.owned_view,cx)?{self.phase=6}},_=>{}}Ok(self.phase>=2)}
