 pub async fn advance<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(runtime,None,cx).await}
 pub async fn advance_surface<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,surface:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.advance_selected(runtime,Some(surface),cx).await}
 pub async fn close_step<PA:PluginApp>(&mut self,runtime:&PluginRuntime<PA>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if let Some(capture)=self.capture.as_mut(){if !capture.terminal_is_empty(){with_instances_turn_mut(runtime,|list|{let mut instance=find_instance(list,self.instance)?;capture.close_step(&mut instance.surface_contexts,cx)}).await?;return Ok(false)}let d=OriginalSurfaceViewCapture::release_demand();forgotten(cx,d,||{self.capture.take();})?;return Ok(false)}self.close_owned(cx)}
 /// 📏️ The selected original registry and retained body determine the next physical close action.
 pub fn close_demands(&self,registry:&semio_plugin_plugin_program::surface_context::SurfaceContexts)->Result<RetirementDemand,ValueError>{if !self.allocation.terminal_is_empty(){return self.allocation.close_demand()}if let Some(capture)=self.capture.as_ref(){return if capture.terminal_is_empty(){Ok(OriginalSurfaceViewCapture::release_demand())}else{capture.close_demands(registry)}}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.frame_failure.is_some(){return self.retirement.next_owner_demands::<OriginalConstructionFailure>(true,&None,self.body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,self.body)}if self.owned_view.is_some(){return self.retirement.next_owner_demands::<semio_framework::ViewModel>(true,&None,self.body)}if self.view.is_some(){return Ok(semio_plugin_job_receiving::original_steps::fixed::<(Option<std::sync::Arc<semio_framework::ViewModel>>,Option<semio_framework_value::retirement::arc_custody::ArcLease<semio_framework::ViewModel>>)>())}if self.lease.is_some(){return self.retirement.next_owner_demands::<semio_framework_value::retirement::arc_custody::ArcLease<semio_framework::ViewModel>>(true,&None,self.body)}if self.actor.is_some(){return self.retirement.next_owner_demands::<String>(true,&None,self.body)}Ok(Default::default())}
 fn close_owned(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.allocation.phase()!=semio_framework_value::native_decoding::NativeReceivingEffectPhase::Empty{return Err(invalid().into())}if self.allocation.has_birth(){let d=self.allocation.close_demand()?;retired(cx,d,|effect|self.allocation.close_step(effect))?;return Ok(false)}if !self.retirement.is_empty(){let d=self.retirement.next_owner_demands::<()>(false,&None,self.body)?;retired(cx,d,|effect|self.retirement.step_granted(effect.grant().maximum_copy_bytes,effect))?;return Ok(false)}macro_rules! close{($field:ident,$ty:ty)=>{if self.$field.is_some(){let d=self.retirement.next_owner_demands::<$ty>(true,&None,self.body)?;retired(cx,d,|effect|begin(&mut self.retirement,&mut self.$field,effect))?;return Ok(false)}}}close!(frame_failure,OriginalConstructionFailure);if !self.frame.terminal_is_empty(){self.frame.close_step(cx)?;return Ok(false)}close!(metadata,ActionMeta);close!(owned_view,semio_framework::ViewModel);if self.view.is_some(){forgotten(cx,fixed::<(Option<std::sync::Arc<semio_framework::ViewModel>>,Option<semio_framework_value::retirement::arc_custody::ArcLease<semio_framework::ViewModel>>)>(),||{*self.lease=self.view.take().map(semio_framework_value::retirement::arc_custody::ArcLease::new);})?;return Ok(false)}close!(lease,semio_framework_value::retirement::arc_custody::ArcLease<semio_framework::ViewModel>);close!(actor,String);Ok(true)}
  pub fn terminal_is_empty(&self)->bool{self.allocation.terminal_is_empty()&&self.frame_failure.is_none()&&self.frame.terminal_is_empty()&&self.capture.is_none()&&self.owned_view.is_none()&&self.view.is_none()&&self.lease.is_none()&&self.actor.is_none()&&self.metadata.is_none()&&self.retirement.is_empty()}
